import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TokenBuffer#writeObject.
 */
public class TokenBuffer_writeObject_TriageGen1Test {

    private ObjectMapper mapper;
    private ObjectCodec codec;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        codec = mapper.getCodec();
    }

    @Test
    public void testWriteObjectWithCodec() throws IOException {
        // Arrange
        TokenBuffer buffer = new TokenBuffer(codec);
        Map<String, Object> testData = new HashMap<>();
        testData.put("key", "value");
        testData.put("number", 123);

        // Act
        buffer.writeObject(testData);

        // Assert
        // Since writeObject calls _append(VALUE_EMBEDDED_OBJECT, value),
        // we verify the buffer contains the expected token.
        assertEquals(JsonToken.VALUE_EMBEDDED_OBJECT, buffer.firstToken());

        // Verify serialization matches the object
        JsonGenerator gen = buffer.asParser(codec).getCodec().getFactory().createGenerator(new java.io.StringWriter());
        buffer.serialize(gen);
        // Note: TokenBuffer's serialize logic for VALUE_EMBEDDED_OBJECT 
        // depends on the internal implementation of _append and serialize.
        // Given the provided snippet, we ensure no exception is thrown and token is set.
    }

    @Test
    public void testWriteObjectWithoutCodec() throws IOException {
        // Arrange: Create buffer with null codec to test the "Tricky choice" mentioned in comments
        TokenBuffer buffer = new TokenBuffer(null);
        Object testValue = "someValue";

        // Act & Assert
        // The comment says: "if no codec, should we err out, or just embed? For now, do latter."
        // This implies it should NOT throw a JsonMappingException even if codec is null.
        try {
            buffer.writeObject(testValue);
        } catch (Exception e) {
            fail("writeObject should not throw exception even if codec is null, per implementation comments.");
        }

        assertEquals(JsonToken.VALUE_EMBEDDED_OBJECT, buffer.firstToken());
    }

    @Test
    public void testWriteObjectWithNullValue() throws IOException {
        // Arrange
        TokenBuffer buffer = new TokenBuffer(codec);

        // Act
        buffer.writeObject(null);

        // Assert
        assertEquals(JsonToken.VALUE_EMBEDDED_OBJECT, buffer.firstToken());
    }

    @Test
    public void testWriteObjectWithComplexObject() throws IOException {
        // Arrange
        TokenBuffer buffer = new TokenBuffer(codec);
        class Inner {
            public String name = "test";
        }
        Inner inner = new Inner();

        // Act
        buffer.writeObject(inner);

        // Assert
        assertEquals(JsonToken.VALUE_EMBEDDED_OBJECT, buffer.firstToken());
    }

    @Test
    public void testWriteObjectWithPrimitiveWrapper() throws IOException {
        // Arrange
        TokenBuffer buffer = new TokenBuffer(codec);
        Integer value = 42;

        // Act
        buffer.writeObject(value);

        // Assert
        assertEquals(JsonToken.VALUE_EMBEDDED_OBJECT, buffer.firstToken());
    }
}
